import{describe,it,expect}from"vitest";describe("Dynamic Offline PWA Caching Strategy",()=>{it("sw.js supports Stale-While-Revalidate and Cache-First dynamic asset strategies",async()=>{const t=await(import("fs")),e=(await(import("path"))).resolve(__dirname,"../../sw.js"),i=t.readFileSync(e,"utf8");expect(i).toContain("CACHE_NAME_PAGES"),expect(i).toContain("CACHE_NAME_STATIC"),expect(i).toContain("caches.open")}),it("sw-register.js initializes offline status banner logic",async()=>{const t=await(import("fs")),e=(await(import("path"))).resolve(__dirname,"../../sw-register.js"),i=t.readFileSync(e,"utf8");expect(i).toContain("offline-status-banner"),expect(i).toContain("You are currently offline — serving cached content")})});